SELECT C.Customer_ID, C.Customer_Details, S.Service_Details, C.Customer_Interactions_ID, C.Customer_Interaction_ID, C.Status_Code, C.Services_and_Channels_Details, S.Channel_Details FROM Customers C JOIN Customers_and_Services K ON C.Customer_ID = K.Customers_and_Services_ID JOIN Services S ON K.Service_ID = S.Service_ID JOIN Customer_Interactions CI ON K.Customer_ID = CI.Customer_ID JOIN Channels H ON CI.Channel_ID = H.Channel_ID WHERE H.Channel_Details = '15 ij' AND S.Service_Details IS NOT NULL;
