SELECT Analytical_Layer.Analytical_Layer_Type_Code, COUNT(Customer_Interactions.Customer_ID) AS Usage_Count FROM Customers_and_Services JOIN Customer_Interactions ON Customers_and_Services.Customers_and_Services_ID = Customer_Interactions.Customer_ID JOIN Analytical_Layer ON Customers_and_Services.Customers_and_Services_ID = Analytical_Layer.Customers_and_Services_ID GROUP BY Analytical_Layer.Analytical_Layer_Type_Code
