SELECT name, Model_year FROM Vehicles ORDER BY Model_year DESC;
SELECT DISTINCT Type_of_powertrain FROM Vehicles;
SELECT DISTINCT Type_of_powertrain FROM Vehicles;
SELECT Customers.name, Vehicles.Type_of_powertrain, Vehicles.Annual_fuel_cost FROM Customers JOIN Vehicles ON Customers.id = Vehicles.customer_id WHERE Vehicles.Model_year IN ('2013', '2014')
SELECT Customers.name, Vehicles.Type_of_powertrain, Vehicles.Annual_fuel_cost FROM Customers INNER JOIN Renting_history ON Customers.id = Renting_history.customer_id INNER JOIN Vehicles ON Renting_history.vehicles_id = Vehicles.id WHERE Vehicles.Model_year IN (2013, 2014)
SELECT V.Type_of_powertrain, C.name, R.customer_id FROM Customers C JOIN Renting_history R ON C.id = R.customer_id JOIN Vehicles V ON R.vehicles_id = V.id WHERE R.Model_year IN ('2014', '2013')
SELECT DISCOUNT.Type_of_powertrain FROM Discount INNER JOIN Vehicles ON Discount.id = Vehicles.Type_of_powertrain INNER JOIN Renting_history ON Vehicles.id = Renting_history.vehicles_id INNER JOIN Customers ON Renting_history.customer_id = Customers.id WHERE Model_year IN ('2013', '2014')
SELECT Type_of_powertrain, COUNT(Vehicles.id) AS number_of_vehicles FROM Vehicles JOIN Renting_history ON Vehicles.id = Renting_history.vehicles_id JOIN Customers ON Renting_history.customer_id = Customers.id GROUP BY Type_of_powertrain
SELECT Type_of_powertrain, COUNT(*) AS count FROM Vehicles GROUP BY Type_of_powertrain
SELECT V.Type_of_powertrain, COUNT(V.id) AS vehicle_count FROM Vehicles V JOIN Renting_history R ON V.id = R.vehicles_id GROUP BY V.Type_of_powertrain ORDER BY COUNT(V.id) DESC;
SELECT DISTINCT Discount.name AS Discount_Type, COUNT(DISTINCT Discount.name) AS Most_Common_Type FROM Discount JOIN Renting_history ON Discount.id = Renting_history.discount_id GROUP BY Discount.name ORDER BY COUNT(DISTINCT Discount.name) DESC;
SELECT MIN(Annual_fuel_cost), MAX(Annual_fuel_cost), AVG(Annual_fuel_cost) FROM Vehicles;
SELECT MIN(Annual_fuel_cost), MAX(Annual_fuel_cost), AVG(Annual_fuel_cost) AS Average_Annual_Fuel_Cost FROM Vehicles;
SELECT V.name, V.Model_year FROM Vehicles V JOIN Customers C ON V.customer_id = C.id WHERE V.City_fuel_economy_rate <= V.Highway_fuel_economy_rate;
SELECT name, Model_year FROM Vehicles JOIN Customers ON Vehicles.id = Customers.id WHERE City_fuel_economy_rate <= Highway_fuel_economy_rate;
SELECT Type_of_powertrain, AVG(Vehicles.Annual_fuel_cost) AS Average_Annual_Fuel_Cost FROM Vehicles JOIN Customers ON Vehicles.customer_id = Customers.id GROUP BY Type_of_powertrain HAVING COUNT(Vehicles.id) >= 2;
SELECT V.Type_of_powertrain, AVG(V.Annual_fuel_cost) AS Average_Annual_Fuel_Cost FROM Vehicles V JOIN Renting_history RH ON V.id = RH.vehicles_id JOIN Customers C ON RH.customer_id = C.id GROUP BY V.Type_of_powertrain
SELECT Customers.name, Customers.age, Customers.membership_credit FROM Customers;
SELECT Customers.name, Customers.age, Customers.membership_credit FROM Customers;
SELECT Customers.name, Customers.age FROM Customers INNER JOIN Renting_history ON Customers.id = Renting_history.customer_id WHERE Renting_history.discount_id = (SELECT Discount.id FROM Discount ORDER BY Discount.membership_credit DESC LIMIT 1) AND Customers.membership_credit = (SELECT MAX(membership_credit) FROM Customers)
SELECT Customers.name, Customers.age, Customers.membership_credit FROM Customers JOIN Discount ON Customers.id = Discount.discount_id JOIN Renting_history ON Customers.id = Renting_history.customer_id JOIN Vehicles ON Renting_history.vehicles_id = Vehicles.id GROUP BY Customers.id ORDER BY Customers.membership_credit DESC LIMIT 1;
SELECT AVG(age) FROM Customers WHERE membership_credit > (SELECT AVG(membership_credit) FROM Customers)
