SELECT Customers.id, Customers.name, Customers.age, Customers.membership_credit, Discount.id, Discount.name, Discount.membership_credit, Vehicles.id, Vehicles.name, Vehicles.Model_year, Vehicles.Type_of_powertrain, Vehicles.Combined_fuel_economy_rate, Vehicles.City_fuel_economy_rate, Vehicles.Highway_fuel_economy_rate, Vehicles.Cost_per_25_miles, Vehicles.Annual_fuel_cost, Vehicles.Notes FROM Customers INNER JOIN Discount ON Customers.id = Discount.discount_id INNER JOIN Vehicles ON Vehicles.id = Renting_history.vehicles_id;
SELECT Customers.id, Customers.name, Customers.age, Customers.membership_credit, Discount.id, Discount.name, Discount.membership_credit, Vehicles.id, Vehicles.name, Vehicles.Model_year, Vehicles.Type_of_powertrain, Vehicles.Combined_fuel_economy_rate, Vehicles.City_fuel_economy_rate, Vehicles.Highway_fuel_economy_rate, Vehicles.Cost_per_25_miles, Vehicles.Annual_fuel_cost, Notes FROM Customers JOIN Discount ON Customers.id = Discount.discount_id JOIN Vehicles ON Vehicles.id = Renting_history.vehicles_id;
SELECT Customers.name, SUM(Renting_history.total_hours) AS total_hours FROM Customers JOIN Renting_history ON Customers.id = Renting_history.customer_id GROUP BY Customers.id;
SELECT Customers.name, SUM(Renting_history.total_hours) AS total_rental_hours FROM Customers JOIN Renting_history ON Customers.id = Renting_history.customer_id GROUP BY Customers.name;
SELECT V.name AS vehicle_name FROM Vehicles V JOIN Customers C ON V.customer_id = C.id WHERE V.Membership_credit IS NULL;
SELECT DISTINCT Vehicles.name FROM Vehicles JOIN Customers ON Customers.id = Customers.id WHERE Customers.id NOT IN (SELECT customer_id FROM Renting_history WHERE discount_id = NULL OR vehicles_id = NULL OR total_hours = 0)
SELECT Customers.name FROM Customers JOIN Renting_history ON Customers.id = Renting_history.customer_id WHERE Renting_history.discount_id IS NOT NULL AND Renting_history.vehicles_id IS NOT NULL AND Renting_history.total_hours >= 2
SELECT Customers.name FROM Customers INNER JOIN Renting_history ON Customers.id = Renting_history.customer_id WHERE Renting_history.discount_id IS NOT NULL AND Renting_history.vehicles_id IS NOT NULL AND Renting_history.total_hours > 0;
SELECT Customers.name, Vehicles.Model_year FROM Customers INNER JOIN Renting_history ON Customers.id = Renting_history.customer_id INNER JOIN Discount ON Renting_history.discount_id = Discount.id INNER JOIN Vehicles ON Renting_history.vehicles_id = Vehicles.id GROUP BY Customers.name, Vehicles.Model_year ORDER BY COUNT(Renting_history.id) DESC LIMIT 1;
SELECT Customers.name, Vehicles.Model_year FROM Customers INNER JOIN Renting_history ON Customers.id = Renting_history.customer_id INNER JOIN Vehicles ON Renting_history.vehicles_id = Vehicles.id GROUP BY Customers.name, Vehicles.Model_year ORDER BY Total_hours DESC LIMIT 1;
SELECT Vehicles.name, Rentals.total_hours FROM Rentals INNER JOIN Vehicles ON Rentals.vehicles_id = Vehicles.id ORDER BY Rentals.total_hours DESC;
SELECT name, total_hours FROM Renting_history INNER JOIN Customers ON Renting_history.customer_id = Customers.id INNER JOIN Vehicles ON Renting_history.vehicles_id = Vehicles.id ORDER BY total_hours DESC;
SELECT Discount.name, COUNT(Renting_history.vehicles_id) AS total_renting_history FROM Customers JOIN Discount ON Customers.id = Discount.id JOIN Renting_history ON Customers.id = Renting_history.customer_id GROUP BY Discount.id, Discount.name ORDER BY total_renting_history DESC
SELECT Discount.name AS discount_name FROM Discount INNER JOIN Renting_history ON Discount.id = Renting_history.discount_id GROUP BY Discount.id ORDER BY COUNT(Renting_history.id) DESC LIMIT 1;
SELECT Customers.name, Vehicles.Type_of_powertrain FROM Customers JOIN Renting_history ON Customers.id = Renting_history.customer_id JOIN Vehicles ON Renting_history.vehicles_id = Vehicles.id WHERE Vehicles.Combined_fuel_economy_rate > 30;
SELECT C.name, V.Type_of_powertrain FROM Customers C JOIN Vehicles V ON C.id = V.customer_id WHERE V.Combined_fuel_economy_rate > 30;
