SELECT S.student_id, S.bio_data, S.student_details, B.behaviour_monitoring_details, T.transcript_details, T.date_of_transcript, T.transcript_id, T.student_id, T.date_of_transcript, T.transcript_details, T.date_of_transcript FROM Students S JOIN Transcripts T ON S.student_id = T.student_id JOIN Behaviour_Monitoring B ON T.student_id = B.student_id WHERE T.date_of_transcript IS NOT NULL AND B.behaviour_monitoring_details IS NOT NULL AND T.transcript_details IS NOT NULL AND T.date_of_transcript IS NOT NULL AND S.bio_data IS NOT NULL AND S.student_details IS NOT NULL AND S.student_id IS NOT NULL AND S.student_id IS NOT NULL AND T.student_id IS NOT NULL AND T.student_id IS NOT NULL AND B.behaviour_monitoring_details IS NOT NULL AND B.behaviour_monitoring_details IS NOT NULL AND T.transcript_details IS NOT NULL AND T.transcript_details IS NOT NULL AND S.student_id IS NOT NULL AND S.student_id IS NOT NULL;
