SELECT detention.datetime_detention_start, detention.datetime_detention_end, detention_summary FROM Detention detention JOIN Students student ON detention.student_id = student.student_id JOIN Ref_Detention_Type detention_type ON detention.detention_type_code = detention_type.detention_type_code;
SELECT Detention.datetime_detention_start, Detention.datetime_detention_end FROM Detention INNER JOIN Students_Addresses ON Detention.student_id = Students_Addresses.student_id INNER JOIN Addresses ON Students_Addresses.address_id = Addresses.address_id INNER JOIN Ref_Address_Types ON Students_Addresses.address_type_code = Ref_Address_Types.address_type_code INNER JOIN Ref_Detention_Type ON Detention.detention_type_code = Ref_Detention_Type.detention_type_code;
