SELECT s.student_id, t.student_id, t.teacher_id, t.class_details FROM Students s JOIN Transcripts t ON s.student_id = t.student_id JOIN Classes c ON t.student_id = c.student_id JOIN Behaviour_Monitoring b ON s.student_id = b.student_id JOIN Student_Events e ON s.student_id = e.student_id JOIN Ref_Event_Types e_type ON e.event_type_code = e_type.event_type_code JOIN Ref_Address_Types e_type2 ON e.address_type_code = e_type2.address_type_code JOIN Addresses a ON e.address_id = a.address_id JOIN Detention d ON s.student_id = d.student_id JOIN Ref_Detention_Type d_type ON d.detention_type_code = d_type.detention_type_code JOIN Achievement_Type a_type ON e.achievement_type_code = a_type.achievement_type_code JOIN Achievement a ON e.achievement_id = a.achievement_id;
SELECT COUNT(*) AS total_courses, teacher_id AS teacher_id FROM Classes JOIN Students ON Classes.student_id = Students.student_id JOIN Teachers ON Classes.teacher_id = Teachers.teacher_id GROUP BY teacher_id ORDER BY COUNT(*) DESC;
SELECT t.teacher_id, COUNT(CASE WHEN t.class_id IS NOT NULL THEN t.class_id END) AS number_of_courses FROM Classes t JOIN Teachers ON t.teacher_id = Teachers.teacher_id GROUP BY t.teacher_id ORDER BY number_of_courses DESC;
SELECT COUNT(DISTINCT student_id) AS max_courses, student_id AS student_id_of_most_courses FROM Students JOIN Transcripts ON Transcripts.student_id = Students.student_id GROUP BY student_id ORDER BY COUNT(DISTINCT student_id) DESC LIMIT 1;
SELECT student_id, COUNT(*) AS number_of_courses FROM Transcripts JOIN Students ON Transcripts.student_id = Students.student_id GROUP BY student_id ORDER BY number_of_courses DESC;
SELECT student_id, student_details, behaviour_monitoring_details, transcript_details, achievement_details, other_details FROM Students, Transcripts, Behaviour_Monitoring, Achievements, Student_Loans, Detention, Student_Events, Students_Addresses WHERE Students.student_id = Transcripts.student_id AND Transcripts.student_id = Behaviour_Monitoring.student_id AND Behaviour_Monitoring.student_id = Achievements.student_id AND Achievements.student_id = Student_Loans.student_id AND Student_Loans.student_id = Detention.student_id AND Detention.student_id = Student_Events.student_id AND Student_Events.student_id = Students_Addresses.student_id AND Students_Addresses.address_id = Addresses.address_id AND Addresses.address_type_code = Ref_Address_Types.address_type_code AND Addresses.address_type_code = Ref_Detention_Type.detention_type_code AND Detention.detention_type_code = Ref_Detention_Type.detention_type_code AND Detention.student_id = Students_Addresses.student_id AND Students_Addresses.date_from = Detention.datetime_detention_start AND Detention.datetime_detention_end AND Students_Addresses.date_to = Detention.datetime_detention_end AND Students_Addresses.student_id = Students.Addresses.student_id;
SELECT student_id, transcript_details FROM Transcripts INNER JOIN Students ON Transcripts.student_id = Students.student_id WHERE Transcripts.transcript_details IS NOT NULL;
SELECT detention_type_code, detention_type_description, detention_summary FROM Detention ORDER BY detention_summary ASC LIMIT 1;
SELECT detention_type_code, detention_type_description, detention_summary FROM Detention ORDER BY detention_summary ASC LIMIT 1;
