{ "sql": "SELECT S.student_id, S.bio_data, S.student_details, S.student_events, S.Student_Events.event_date, S.Student_Events.other_details, S.Student_Events.event_type_code, S.Student_Events.student_id, S.Student_Events.date_of_event, S.Student_Events.date_from, S.Student_Events.date_to, S.Student_Events.event_summary\nFROM Students S\nJOIN Student_Events SE ON S.student_id = SE.student_id\nJOIN Detention D ON SE.student_id = D.student_id\nJOIN Student_Addresses SA ON SE.student_id = SA.student_id\nJOIN Addresses A ON SA.address_id = A.address_id\nJOIN Ref_Address_Types RA ON SA.address_type_code = RA.address_type_code\nJOIN Ref_Detention_Type DT ON D.detention_type_code = DT.detention_type_code\nJOIN Ref_Event_Types RTE ON SE.event_type_code = RTE.event_type_code\nJOIN Ref_Achievement_Type RA1 ON SA.achievement_type_code = RA1.achievement_type_code\nJOIN Ref_Address_Types RA2 ON SA.address_type_code = RA2.address_type_code\nJOIN Ref_Detention_Type DT2 ON D.detention_type_code = DT2.detention_type_code\nJOIN Ref_Address_Types RA3 ON SA.address_type_code = RA3.address_type_code\nJOIN Ref_Detention_Type DT3 ON D.detention_type_code = DT3.detention_type_code\nJOIN Ref_Address_Types RA4 ON SA.address_type_code = RA4.address_type_code\nJOIN Ref_Detention_Type DT4 ON D.detention_type_code = DT4.detention_type_code\nJOIN Ref_Address_Types RA5 ON SA.address_type_code = RA5.address_type_code\nJOIN Ref_Detention_Type DT5 ON D.detention_type_code = DT5.detention_type_code\nJOIN Ref_Address_Types RA6 ON SA.address_type_code = RA6.address_type_code\nJOIN Ref_Detention_Type DT6 ON D.detention_type_code = DT6.detention_type_code\nJOIN Ref_Address_Types RA7 ON SA.address_type_code = RA7.address_type_code\nJOIN Ref_Detention_Type DT7 ON D.detention_type_code = DT7.detention_type_code\nJOIN Ref_Address_Types RA8 ON SA.address_type_code = RA8.address_type_code\nJOIN Ref_Detention_Type DT8 ON D.detention_type_code = DT8.detention_type_code\nJOIN Ref_Address_Types RA9 ON SA.address_type_code = RA9.address_type_code\nJOIN Ref_Detention_Type DT9 ON D.detention_type_code = DT9.detention_type_code\nJOIN Ref_Address_Types RA10 ON SA.address_type_code = RA10.address_type_code\nJOIN Ref_Detention_Type DT10 ON D.detention_type_code = DT10.detention_type_code\nJOIN Ref_Address_Types RA11 ON SA.address_type_code = RA11.address_type_code\nJOIN Ref_Detention_Type DT11 ON D.detention_type_code = DT11.detention_type_code\nJOIN Ref_Address_Types RA12 ON SA.address_type_code = RA12.address_type_code\nJOIN Ref_Detention_Type DT12 ON D.detention_type_code = DT12.detention_type_code\nJOIN Ref_Address_Types RA13 ON SA.address_type_code = RA13.address_type_code\nJOIN Ref_Detention_Type DT13 ON D.detention_type_code = DT13.detention_type_code\nJOIN Ref_Address_Types RA14 ON SA.address_type_code = RA14.address_type_code\nJOIN Ref_Detention_Type DT14 ON D.detention_type_code = DT14.detention_type_code\nJOIN Ref_Address_Types RA15 ON SA.address_type_code = RA15.address_type_code\nJOIN Ref_Detention_Type DT15 ON D.detention_type_code = DT15.detention_type_code\nJOIN Ref_Address_Types RA16 ON SA.address_type_code = RA16.address_type_code\nJOIN Ref_Detention_Type DT16 ON D.detention_type_code = DT16.detention_type_code
