SELECT Orders.IdOrder, Clients.Name FROM Client JOIN Orders ON Client.IdClient = Orders.IdClient;
SELECT Orders.IdOrder, Clients.Name AS ClientName FROM Orders INNER JOIN Clients ON Orders.IdClient = Clients.IdClient;
SELECT Author.Name, Book.amount AS book_count FROM Author INNER JOIN Author_Book ON Author.idAuthor = Author_Book.ISBN JOIN Book ON Author_Book.ISBN = Book.ISBN;
SELECT Author.Name, COUNT(Book.ISBN) AS TotalBooks FROM Author JOIN Author_Book ON Author.idAuthor = Author_Book.idAuthor JOIN Book ON Author_Book.ISBN = Book.ISBN GROUP BY Author.Name
SELECT Book.ISBN, Orders.IdOrder, Orders.DateOrder, Orders.DateExped, Author_Book.ISBN, Author_Book.Author FROM Books_Order INNER JOIN Author_Book ON Books_Order.ISBN = Author_Book.ISBN INNER JOIN Author ON Author_Book.Author = Author.idAuthor INNER JOIN Orders ON Orders.IdOrder = Books_Order.IdOrder INNER JOIN Client ON Orders.IdClient = Client.IdClient;
SELECT B.ISBN, COUNT(*) AS order_count FROM Books_Order B JOIN Book ON B.ISBN = B.ISBN JOIN Author_Book ON B.ISBN = Author_Book.ISBN JOIN Author ON Author_Book.Author = Author.idAuthor GROUP BY B.ISBN
SELECT B.ISBN, B.Title, B.PurchasePrice, B.SalePrice, A.Name, A.Address, A.NumCC, O.IdOrder, O.DateOrder, O.DateExped, A.Author_Book.ISBN, A.Author_Book.Author, O.amount FROM Books_Order O JOIN Author_Book A ON O.ISBN = A.ISBN JOIN Book B ON A.ISBN = B.ISBN JOIN Author A_Book ON A.ISBN = A_Book.ISBN JOIN Client C ON O.IdClient = C.IdClient;
SELECT B.ISBN, A.Name, O.DateOrder, O.amount AS total_order FROM Books_Order O JOIN Books B ON O.ISBN = B.ISBN JOIN Author A ON B.Author = A.idAuthor GROUP BY B.ISBN, A.Name, O.DateOrder, O.amount;
SELECT B.Title AS BookTitle FROM Book B JOIN Orders O ON B.ISBN = O.ISBN JOIN Author_Book A ON B.ISBN = A.ISBN JOIN Author A2 ON A.ISBN = A2.ISBN JOIN Books_Order BDO ON B.ISBN = BDO.ISBN GROUP BY B.ISBN ORDER BY BDO.amount DESC LIMIT 1;
SELECT Book.Title, COUNT(Books_Order.amount) AS total_orders FROM Books_Order INNER JOIN Book ON Books_Order.ISBN = Book.ISBN INNER JOIN Orders ON Orders.IdOrder = Books_Order.IdOrder GROUP BY Book.Title ORDER BY total_orders DESC LIMIT 1
SELECT Book.Title, Book.PurchasePrice FROM Book JOIN Author_Book ON Book.ISBN = Author_Book.ISBN JOIN Author ON Author.ISBN = Author_Book.Author WHERE Book.PurchasePrice ORDER BY Book.PurchasePrice DESC;
SELECT Book.Title, Book.PurchasePrice FROM Book JOIN Books_Order ON Book.ISBN = Books_Order.ISBN JOIN Orders ON Books_Order.IdOrder = Orders.IdOrder JOIN Author_Book ON Author_Book.ISBN = Books_Order.ISBN JOIN Author ON Author.ISBN = Author_Book.Author WHERE Books_Order.amount = (SELECT MAX(amount) FROM Books_Order)
