SELECT MAX(p.height_mm), MAX(p.painterID) FROM Paintings p JOIN Artists a ON p.painterID = a.artistID WHERE p.year < 1900
SELECT paintings.height_mm, paintings.painterID FROM Paintings INNER JOIN Artists ON Paintings.painterID = Artists.artistID WHERE paintings.year < 1900 ORDER BY paintings.height_mm DESC LIMIT 1;
SELECT Artists.birthYear, MAX(Paintings.height_mm) AS maxHeight, MAX(Paintings.width_mm) AS maxWidth FROM Paintings JOIN Artists ON Paintings.painterID = Artists.artistID GROUP BY Artists.birthYear;
SELECT paintings.title, paintings.year, paintings.height_mm, paintings.width_mm FROM Paintings INNER JOIN Artists ON Paintings.painterID = Artists.artistID;
SELECT artistID, lname, fname, AVG(height_mm) AS average_height, AVG(width_mm) AS average_width FROM Paintings JOIN Artists ON Paintings.painterID = Artists.artistID GROUP BY artistID ORDER BY lname, fname
SELECT AVG(p.height_mm) AS averageHeight, AVG(p.width_mm) AS averageWidth, AVG(p.painterID) AS averagePainterID, p.title, p.year, p.medium, p.mediumOn, p.location FROM Paintings p JOIN Artists a ON p.painterID = a.artistID GROUP BY a.lname, a.fname ORDER BY a.lname, a.fname
SELECT fname, COUNT(paintingID) AS numWorks FROM Artists INNER JOIN Paintings ON Artists.artistID = Paintings.painterID GROUP BY fname
SELECT artists.fname, COUNT(Paintings.paintingID) AS num_paintings FROM Artists INNER JOIN Paintings ON Paintings.painterID = Artists.artistID GROUP BY artists.fname
SELECT artists.deathYear FROM Artists INNER JOIN Paintings ON Artists.artistID = Paintings.painterID WHERE Paintings.height_mm IS NULL OR Paintings.width_mm IS NULL
SELECT artistID, lname, fname, birthYear, deathYear FROM Artists INNER JOIN Paintings ON Paintings.painterID = Artists.artistID INNER JOIN Sculptures ON Sculptures.sculptorID = Artists.artistID WHERE Paintings.height_mm < 4;
SELECT artists.deathYear FROM Artists INNER JOIN Paintings ON Paintings.painterID = Artists.artistID INNER JOIN Sculptures ON Sculptures.sculptorID = Artists.artistID WHERE Paintings.year < Sculptures.year;
SELECT artistID, lname, fname, birthYear, deathYear FROM Artists INNER JOIN Paintings ON Paintings.painterID = Artists.artistID INNER JOIN Sculptures ON Sculptures.sculptorID = Artists.artistID ORDER BY birthYear DESC;
SELECT paintings.paintingID, paintings.height_mm FROM Paintings INNER JOIN Artists ON Paintings.painterID = Artists.artistID WHERE paintings.width_mm > (SELECT MAX(width_mm) FROM Paintings WHERE paintings.location = 'gallery 240')
SELECT paintings.height_mm, paintings.painterID FROM Paintings INNER JOIN Artists ON Paintings.painterID = Artists.artistID WHERE paintings.year = (SELECT MAX(year) FROM Paintings WHERE location = '240') ORDER BY paintings.height_mm DESC;
SELECT paintings.paintingID FROM Paintings INNER JOIN Artists ON Paintings.painterID = Artists.artistID WHERE paintings.year < (SELECT MAX(year) FROM Paintings WHERE location = 'gallery 240')
SELECT paintings.paintingID, artists.artistID FROM Paintings INNER JOIN Artists ON Paintings.painterID = Artists.artistID WHERE paintings.year < sculptures.year;
SELECT p.paintingID FROM Paintings p JOIN Artists a ON p.painterID = a.artistID WHERE p.year > 1900 AND p.height_mm > (SELECT MAX(height_mm) FROM Paintings p2 WHERE p2.year > 1900)
SELECT paintings.painterID FROM Paintings INNER JOIN Artists ON Paintings.painterID = Artists.artistID WHERE year > 1900 AND height_mm > (SELECT MAX(height_mm) FROM Paintings WHERE year > 1900)
SELECT artistID, fname, lname, birthYear, deathYear FROM Artists ORDER BY artistID DESC LIMIT 3;
SELECT artistID, lname, fname, birthYear, deathYear FROM Artists JOIN Paintings ON Paintings.painterID = Artists.artistID GROUP BY artistID ORDER BY birthYear DESC LIMIT 10
SELECT paintings.paintingID, paintings.title, paintings.year, paintings.medium, paintings.mediumOn, paintings.location FROM Paintings JOIN Artists ON Paintings.painterID = Artists.artistID ORDER BY paintings.year;
SELECT paintings.paintingID, paintings.title, paintings.location, paintings.year, artists.artistID, paintings.medium, paintings.mediumOn FROM Paintings INNER JOIN Artists ON Paintings.painterID = Artists.artistID;
SELECT paintings.year, paintings.location, paintings.title, paintings.height_mm FROM Paintings INNER JOIN Artists ON Paintings.painterID = Artists.artistID WHERE paintings.height_mm > 1000 ORDER BY paintings.title
SELECT artistID, title, year, height_mm, width_mm, medium, mediumOn, location, name FROM Paintings INNER JOIN Artists ON Paintings.painterID = Artists.artistID WHERE height_mm > 1000 ORDER BY year, name
SELECT artists.lname, artists.fname FROM Artists INNER JOIN Paintings ON Paintings.painterID = Artists.artistID WHERE Paintings.title IS NULL OR Paintings.medium IS NULL;
SELECT lname, fname FROM Artists INNER JOIN Paintings ON Paintings.painterID = Artists.artistID WHERE Paintings.medium = 'paint' AND Sculptures.sculptorID IS NULL;
SELECT Paintings.location, Artists.lname, Artists.fname FROM Paintings JOIN Artists ON Paintings.painterID = Artists.artistID WHERE Paintings.year < 1885 AND Paintings.medium = 'medium' AND Paintings.mediumOn = 'canvas'
SELECT paintings.location FROM Paintings INNER JOIN Artists ON Paintings.painterID = Artists.artistID WHERE year > 1885 AND medium = 'canvas' AND paintings.location IS NOT NULL;
SELECT COUNT(*) FROM race;
SELECT COUNT(*) AS number_of_races FROM race;
SELECT driver.Driver_Name, race.Racing_Entrant, race.Winning_team FROM driver JOIN race ON driver.Driver_ID = race.Driver_ID ORDER BY race.Winning_team ASC
SELECT driver.Driver_ID, driver.Driver_Name, driver.Entrant, driver.Constructor, driver.Chassis, driver.Engine, driver.Age, race.Race_Name, race.Pole_Position, race.Fastest_Lap, race.Winning_driver, race.Winning_team, race.Report FROM driver INNER JOIN race ON driver.Driver_ID = race.Driver_ID ORDER BY race.Winning_team, race.Race_Name;
SELECT DISTINCT Driver_Name FROM driver WHERE Pole_Position != 'Junior Strous'
SELECT DISTINCT driver.Driver_ID, driver.Driver_Name, driver.Constructor, driver.Chassis, driver.Engine, driver.Age FROM driver JOIN race ON driver.Driver_ID = race.Driver_ID WHERE race.Pole_Position IS NULL AND race.Winning_driver IS NULL;
SELECT DISTINCT Driver_Name, Age FROM driver ORDER BY Age ASC;
SELECT DISTINCT Driver_Name, Constructor, Age FROM driver ORDER BY Age ASC;
SELECT DISTINCT Entrant FROM driver WHERE Age >= 20;
SELECT DISTINCT Entrant FROM driver WHERE Age >= 20
SELECT MAX(Age), MIN(Age) FROM driver;
SELECT MAX(Age), MIN(Age) FROM driver;
SELECT DISTINCT COUNT(DISTINCT driver.Engine) FROM driver INNER JOIN race ON driver.Driver_ID = race.Driver_ID WHERE Age BETWEEN 20 AND 30 OR Age BETWEEN 30 AND 20
SELECT COUNT(DISTINCT driver.Engine) FROM driver JOIN race ON driver.Driver_ID = race.Driver_ID WHERE race.Age BETWEEN 20 AND 30;
SELECT Driver_Name FROM driver ORDER BY Driver_Name DESC;
SELECT Driver_Name FROM driver ORDER BY Driver_Name DESC;
SELECT driver.Driver_Name, race.Race_Name FROM driver INNER JOIN race ON driver.Driver_ID = race.Driver_ID;
SELECT driver.Driver_Name, race.Race_Name FROM driver INNER JOIN race ON driver.Driver_ID = race.Driver_ID;
SELECT driver.Driver_Name, COUNT(race.Driver_ID) AS num_races FROM driver JOIN race ON driver.Driver_ID = race.Driver_ID GROUP BY driver.Driver_Name;
SELECT COUNT(DISTINCT driver.Driver_ID) FROM driver;
SELECT DISTINCT driver.Age FROM driver JOIN race ON driver.Driver_ID = race.Driver_ID ORDER BY driver.Age DESC LIMIT 1;
SELECT Age FROM driver WHERE Age = (SELECT MAX(Age) FROM race)
SELECT DISTINCT Driver_Name, Age FROM driver INNER JOIN race ON driver.Driver_ID = race.Driver_ID WHERE race.Road IS NOT NULL AND race.Race_Name IS NOT NULL AND race.Report IS NOT NULL;
SELECT DISTINCT Driver_Name, Age FROM driver JOIN race ON driver.Driver_ID = race.Driver_ID WHERE race.Road = 'Road' AND race.Race_Name IS NOT NULL AND race.Pole_Position IS NOT NULL AND race.Fastest_Lap IS NOT NULL AND race.Winning_team IS NOT NULL
SELECT driver.Driver_Name FROM driver WHERE driver.Age >= 26
SELECT Driver_Name FROM driver WHERE Age >= 26;
SELECT Driver_Name FROM driver WHERE Constructor != 'Bugatti'
SELECT Driver_Name FROM driver WHERE Constructor != 'Bugatti' AND Driver_ID IS NOT NULL
SELECT DISTINCT constructor, COUNT(DISTINCT driver.driver_id) AS num_drivers FROM driver JOIN race ON driver.Driver_ID = race.Driver_ID GROUP BY constructor;
SELECT DISTINCT constructor, COUNT(*) AS number_of_drivers FROM driver JOIN race ON driver.Driver_ID = race.Driver_ID GROUP BY constructor;
SELECT Engine, COUNT(*) AS Engine_Count FROM driver JOIN race ON driver.Driver_ID = race.Driver_ID GROUP BY Engine ORDER BY Engine_Count DESC LIMIT 10;
SELECT DISTINCT Engine, COUNT(*) AS Engine_Count FROM driver JOIN race ON driver.Driver_ID = race.Driver_ID GROUP BY Engine
SELECT Engine FROM driver JOIN race ON driver.Driver_ID = race.Driver_ID WHERE race.Race_Name IS NOT NULL AND Engine IS NOT NULL AND DISTINCT Engine;
SELECT DISTINCT Engine FROM driver JOIN race ON driver.Driver_ID = race.Driver_ID WHERE race.Report IS NOT NULL AND race.Road IS NOT NULL AND race.Pole_Position IS NOT NULL
SELECT Driver_Name FROM driver WHERE Driver_ID NOT IN (SELECT Driver_ID FROM race)
SELECT DISTINCT Driver_Name FROM driver WHERE Driver_ID NOT IN (SELECT Driver_ID FROM race)
SELECT DISTINCT Constructor FROM driver WHERE Age < 20 OR Age > 30
SELECT DISTINCT d.Constructor FROM driver d JOIN race r ON d.Driver_ID = r.Driver_ID WHERE r.Age < 20 AND r.Age > 30;
SELECT DISTINCT driver.Driver_ID, driver.Driver_Name, driver.Constructor, driver.Chassis, driver.Engine, driver.Age FROM driver JOIN race ON driver.Driver_ID = race.Driver_ID WHERE race.Winning_team IS NOT NULL AND race.Winning_team IS NOT NULL AND race.Winning_team != '' GROUP BY driver.Driver_ID, driver.Driver_Name, driver.Constructor, driver.Chassis, driver.Engine, driver.Age;
SELECT DISTINCT Winning_team FROM race JOIN driver ON race.Driver_ID = driver.Driver_ID GROUP BY Winning_team HAVING COUNT(Race_Name) > 1
SELECT DISTINCT d.Driver_Name FROM driver d JOIN race r ON d.Driver_ID = r.Driver_ID WHERE r.Pole_Position = 'James Hinchcliffe' AND r.Pole_Position = 'Carl Skerlong'
SELECT DISTINCT Driver_Name FROM driver JOIN race ON driver.Driver_ID = race.Driver_ID WHERE Pole_Position = 'Pole Position' AND Driver_Name IN ('James Hinchcliffe', 'Carl Skerlong')
SELECT DISTINCT Driver_Name FROM driver WHERE Driver_ID NOT IN (SELECT Driver_ID FROM race WHERE Pole_Position = 'James Hinchcliffe' AND Winning_driver != 'James Hinchcliffe')
SELECT Driver_Name FROM driver WHERE Driver_ID NOT IN (SELECT Driver_ID FROM race WHERE Pole_Position = 'Pole Position' AND Winning_driver = 'James Hinchcliffe')
SELECT COUNT(*) FROM languages;
SELECT COUNT(*) AS number_of_languages FROM languages;
SELECT languages.name FROM languages ORDER BY languages.name ASC;
SELECT name FROM languages ORDER BY name
SELECT languages.name FROM languages INNER JOIN official_languages ON languages.id = official_languages.language_id WHERE official_languages.country_id IN (SELECT countries.id FROM countries INNER JOIN official_languages ON countries.id = official_languages.country_id WHERE countries.overall_score > 0)
SELECT languages.name FROM languages JOIN official_languages ON languages.id = official_languages.language_id WHERE official_languages.country_id = (SELECT countries.id FROM countries WHERE countries.name LIKE '%ish%')
SELECT countries.name FROM countries JOIN official_languages ON countries.id = official_languages.country_id ORDER BY countries.overall_score DESC;
SELECT countries.name, countries.overall_score, countries.justice_score, countries.health_score, countries.education_score, countries.economics_score, countries.politics_score FROM countries JOIN official_languages ON countries.id = official_languages.country_id ORDER BY countries.overall_score DESC;
SELECT countries.justice_score, countries.name, countries.overall_score, countries.health_score, countries.education_score, countries.economics_score, countries.politics_score FROM countries JOIN official_languages ON countries.id = official_languages.country_id JOIN languages ON official_languages.language_id = languages.id WHERE countries.name != 'NULL' AND countries.name != '' GROUP BY countries.id, countries.name ORDER BY countries.overall_score DESC;
SELECT AVG(countries.justice_score) AS average_justice_scores FROM countries;
SELECT MAX(health_score), MIN(health_score) FROM countries WHERE name != 'Norway'
SELECT MAX(health_score) AS max_health, MIN(health_score) AS min_health FROM countries WHERE country_id != 10000;
SELECT COUNT(DISTINCT languages.name) FROM languages;
SELECT COUNT(DISTINCT languages.name) FROM languages;
SELECT countries.name, countries.education_score FROM countries ORDER BY countries.education_score DESC;
SELECT countries.name, countries.education_score ORDER BY countries.education_score DESC;
SELECT countries.name FROM countries JOIN official_languages ON countries.id = official_languages.country_id WHERE countries.politics_score ORDER BY countries.politics_score DESC;
SELECT countries.name FROM countries JOIN official_languages ON countries.id = official_languages.country_id WHERE countries.politics_score = (SELECT MAX(politics_score) FROM countries)
SELECT countries.name, languages.name AS official_language FROM countries JOIN official_languages ON countries.id = official_languages.country_id JOIN languages ON official_languages.language_id = languages.id;
SELECT countries.name, languages.name AS official_language FROM countries JOIN languages ON countries.id = languages.country_id;
SELECT languages.name, COUNT(countries.id) AS country_count FROM languages INNER JOIN official_languages ON languages.id = official_languages.language_id GROUP BY languages.name
SELECT languages.name, COUNT(countries.id) AS count_of_countries FROM languages JOIN countries ON languages.id = countries.language_id GROUP BY languages.id
SELECT countries.name, COUNT(countries.id) AS total_countries FROM countries JOIN official_languages ON countries.id = official_languages.country_id GROUP BY countries.id ORDER BY COUNT(countries.id) DESC LIMIT 1
SELECT languages.name AS language, countries.name AS country, languages.name AS language_name, countries.overall_score AS overall_score, countries.justice_score AS justice_score, countries.health_score AS health_score, countries.education_score AS education_score, countries.economics_score AS economics_score, countries.politics_score AS politics_score, languages.name AS language_name FROM languages LEFT JOIN countries ON languages.id = countries.language_id WHERE languages.id = (SELECT id FROM languages ORDER BY languages.name DESC LIMIT 1)
SELECT languages.name AS language, countries.name AS country FROM languages JOIN countries ON countries.id = official_languages.country_id WHERE countries.overall_score > 0 OR countries.justice_score > 0 OR countries.health_score > 0 OR countries.education_score > 0 OR countries.economics_score > 0 OR countries.politics_score > 0;
SELECT DISTINCT l.name AS language, c.name AS country FROM languages l JOIN countries c ON l.id = c.id JOIN official_languages ol ON ol.language_id = l.id AND ol.country_id = c.id GROUP BY l.id, c.id
SELECT AVG(countries.overall_score) AS average_overall_score FROM countries c JOIN official_languages o ON c.id = o.country_id WHERE o.language_id = (SELECT language_id FROM languages WHERE name = 'English')
SELECT AVG(countries.overall_score) FROM countries INNER JOIN official_languages ON countries.id = official_languages.country_id WHERE countries.name = ?
SELECT l.name, o.country_id FROM languages l JOIN official_languages o ON l.id = o.language_id ORDER BY l.name DESC LIMIT 3;
SELECT languages.name, countries.name FROM languages JOIN countries ON languages.id = countries.id JOIN official_languages ON countries.id = official_languages.country_id GROUP BY languages.id, countries.id ORDER BY countries.overall_score DESC LIMIT 3;
SELECT languages.name, countries.overall_score, countries.justice_score, countries.health_score, countries.education_score, countries.economics_score, countries.politics_score FROM countries JOIN official_languages ON countries.id = official_languages.country_id JOIN languages ON official_languages.language_id = languages.id ORDER BY languages.name DESC, countries.overall_score;
SELECT languages.name, countries.name, countries.overall_score, countries.justice_score, countries.health_score, countries.education_score, countries.economics_score, countries.politics_score FROM countries JOIN official_languages ON countries.id = official_languages.country_id JOIN languages ON official_languages.language_id = languages.id ORDER BY languages.name DESC;
SELECT countries.name AS country_name FROM countries JOIN official_languages ON countries.id = official_languages.country_id GROUP BY countries.id ORDER BY official_languages.language_id DESC;
SELECT countries.name, languages.name AS language_name FROM countries JOIN official_languages ON countries.id = official_languages.country_id JOIN languages ON official_languages.language_id = languages.id GROUP BY countries.id ORDER BY languages.name DESC;
SELECT languages.name FROM languages JOIN official_languages ON languages.id = official_languages.language_id WHERE countries.id IS NULL
SELECT l.name FROM languages l JOIN official_languages o ON l.id = o.language_id WHERE o.country_id IS NULL
SELECT countries.name FROM countries JOIN official_languages ON countries.id = official_languages.country_id WHERE languages.name IS NULL
SELECT countries.name FROM countries JOIN official_languages ON countries.id = official_languages.country_id WHERE countries.official_languages IS NULL;
SELECT languages.name FROM languages JOIN countries ON languages.id = countries.id JOIN official_languages ON countries.id = official_languages.country_id WHERE languages.overall_score > 95 AND countries.overall_score < 90;
SELECT languages.name FROM languages JOIN countries ON languages.id = countries.id WHERE countries.overall_score > 95 OR countries.overall_score < 90
SELECT Addresses.country, Addresses.town_city, Addresses.line_1_number_building, Addresses.line_2_number_street, Addresses.line_3_area_locality, Addresses.zip_postcode, Addresses.county_state_province FROM Addresses WHERE Addresses.country IS NOT NULL OR Addresses.town_city IS NOT NULL OR Addresses.line_1_number_building IS NOT NULL OR Addresses.line_2_number_street IS NOT NULL OR Addresses.line_3_area_locality IS NOT NULL OR Addresses.zip_postcode IS NOT NULL OR Addresses.county_state_province IS NOT NULL;
