SELECT Users.login_name, Users.first_name FROM Users INNER JOIN Ref_Property_Types ON Users.age_category_code = Ref_Property_Types.property_type_code INNER JOIN Ref_Room_Types ON Users.room_type_code = Ref_Room_Types.room_type_code INNER JOIN Ref_User_Categories ON Users.user_category_code = Ref_User_Categories.user_category_code WHERE Users.age_category_code = 'Senior' AND Users.user_category_code = 'User' ORDER BY Users.first_name
SELECT Users.first_name, Users.login_name FROM Users INNER JOIN Addresses ON Users.user_address_id = Addresses.address_id INNER JOIN Ref_Property_Types ON Users.user_address_id = Addresses.address_id INNER JOIN Properties ON Addresses.address_id = Properties.property_address_id INNER JOIN Ref_Property_Types ON Properties.property_type_code = Ref_Property_Types.property_type_code INNER JOIN Users ON Users.user_address_id = Users.user_address_id INNER JOIN Ref_User_Categories ON Users.user_category_code = Ref_User_Categories.user_category_code INNER JOIN Ref_Property_Types ON Users.user_category_code = Ref_User_Categories.user_category_code INNER JOIN Ref_Room_Types ON Properties.room_type_code = Ref_Room_Types.room_type_code INNER JOIN Rooms ON Properties.property_id = Rooms.room_id INNER JOIN Property_Features ON Properties.property_id = Property_Features.property_id INNER JOIN Features ON Property_Features.feature_id = Features.feature_id INNER JOIN Property_Photos ON Property_Features.feature_id = Property_Photos.feature_id;
