SELECT COUNT(*) FROM Properties WHERE date_on_market >= DATE_SUB(CURDATE(), INTERVAL 2 DAY) AND date_off_market <= DATE_SUB(CURDATE(), INTERVAL 1 DAY) AND property_name IS NOT NULL;
