SELECT Documents.document_id, Documents.author_name, Documents.document_name, Documents.document_description, Documents.other_details FROM Documents JOIN Authors ON Documents.author_name = Authors.author_name WHERE Authors.author_name = 'Bianka Cummings' AND Documents.author_name = 'Bianka Cummings' GROUP BY Documents.document_id, Documents.author_name, Documents.document_name, Documents.document_description, Documents.other_details;
SELECT Documents.author_name, Documents.document_name, Documents.document_description, Documents.other_details FROM Documents JOIN Authors ON Documents.author_name = Authors.author_name WHERE Documents.document_id = 'Travel to China'
SELECT Authors.author_name, COUNT(DOCUMENTS.author_name) AS document_count FROM Documents INNER JOIN Authors ON Documents.author_name = Authors.author_name GROUP BY Authors.author_name;
SELECT author_name FROM Authors JOIN Documents ON Documents.author_name = Authors.author_name JOIN Documents_Processes ON Documents.Processes.document_id = Documents_Processes.document_id JOIN Process_Status ON Documents_Processes.process_status_code = Process_Status.process_status_code JOIN Process_Outcomes ON Documents_Processes.process_outcome_code = Process_Outcomes.process_outcome_code GROUP BY author_name ORDER BY COUNT(DOCUMENTS.document_id) DESC LIMIT 1;
