SELECT COUNT(*) FROM Agencies
SELECT COUNT(*) FROM Agencies
SELECT agency_id, staff_details FROM Staff JOIN Agencies ON Staff.agency_id = Agencies.agency_id;
SELECT agency_id, agency_details FROM Agencies;
SELECT COUNT(*) AS number_of_clients FROM Clients;
SELECT COUNT(*) FROM Clients;
SELECT Clients.client_id, Clients.client_details FROM Clients JOIN Agencies ON Clients.agency_id = Agencies.agency_id;
SELECT client_id, agency_id, sic_code, client_details FROM Clients;
SELECT Agencies.agency_id, COUNT(Staff_in_Meetings.staff_id) AS client_count FROM Agencies JOIN Staff_in_Meetings ON Agencies.agency_id = Staff_in_Meetings.meeting_id GROUP BY Agencies.agency_id;
SELECT COUNT(DISTINCT agency_id) AS total_clients_per_agency FROM Agencies;
SELECT agency_id, COUNT(client_id) AS client_count FROM Agencies JOIN Clients ON Clients.agency_id = Agencies.agency_id GROUP BY agency_id ORDER BY client_count DESC;
SELECT Agencies.agency_id, Agencies.agency_details FROM Agencies JOIN Staff ON Agencies.agency_id = Staff.agency_id ORDER BY Staff.staff_id DESC LIMIT 1;
SELECT agency_id, agency_details FROM Agencies INNER JOIN Clients ON Clients.agency_id = Agencies.agency_id WHERE Clients.client_id IS NOT NULL AND COUNT(Clients.client_id) >= 2;
SELECT agency_id, agency_details FROM Agencies INNER JOIN Staff ON Agencies.agency_id = Staff.agency_id WHERE Staff.staff_details IS NOT NULL AND Staff.staff_id IS NOT NULL AND COUNT(*) >= 2;
SELECT agencies.agency_id, agencies.agency_details FROM Agencies JOIN Clients ON Clients.agency_id = Agencies.agency_id WHERE Clients.client_details = 'Mac'
SELECT DISTINCT c.client_id, c.sic_code, c.client_details, s.staff_id, s.staff_details FROM Clients c JOIN Staff s ON c.agency_id = s.agency_id WHERE c.client_details LIKE '%Mac%';
SELECT Clients.client_id, Clients.sic_code, Clients.client_details, Agencies.agency_details, Staff.staff_id, Staff.staff_details, Staff_in_Meetings.meeting_outcome, Staff_in_Meetings.billable_yn, Staff_in_Meetings.start_date_time, Staff_in_Meetings.end_date_time, Staff_in_Meetings.purpose_of_meeting, Staff_in_Meetings.other_details FROM Clients JOIN Agencies ON Clients.agency_id = Agencies.agency_id JOIN Staff ON Clients.agency_id = Staff.agency_id JOIN Staff_in_Meetings ON Staff.staff_id = Staff_in_Meetings.staff_id JOIN Meetings ON Staff_in_Meetings.meeting_id = Meetings.meeting_id;
SELECT Clients.client_id, Clients.client_details, Agencies.agency_details, Staff.staff_id, Staff.staff_details, Meetings.meeting_outcome, Meetings.meeting_type, Meetings.billable_yn, Meetings.start_date_time, Meetings.end_date_time, Meetings.purpose_of_meeting, Meetings.other_details FROM Clients JOIN Agencies ON Clients.agency_id = Agencies.agency_id JOIN Staff ON Clients.client_id = Staff.client_id JOIN Staff_in_Meetings ON Staff.staff_id = Staff_in_Meetings.staff_id JOIN Meetings ON Staff_in_Meetings.meeting_id = Meetings.meeting_id;
SELECT sic_code, COUNT(DISTINCT client_id) AS client_count FROM Clients GROUP BY sic_code
SELECT DISTINCT C.sic_code, COUNT(C.client_id) AS total_clients_per_sic_code FROM Clients C JOIN Staff_in_Meetings S ON C.client_id = S.client_id GROUP BY C.sic_code
