SELECT Clients.client_id, Clients.sic_code, Clients.client_details FROM Clients INNER JOIN Agencies ON Clients.agency_id = Agencies.agency_id INNER JOIN Staff ON Clients.agency_id = Staff.agency_id WHERE Clients.sic_code = 'Bad'
SELECT Agencies.agency_id, Agencies.agency_details, Staff.staff_id, Staff.staff_details FROM Agencies JOIN Staff ON Agencies.agency_id = Staff.agency_id WHERE Clients.client_id = Staff.staff_id;
