SELECT COUNT(*) FROM Invoices
SELECT COUNT(*) FROM Invoices;
SELECT Clients.client_id, Clients.status_code, Clients.client_details FROM Clients INNER JOIN Invoices ON Clients.client_id = Invoices.client_id;
SELECT invoice_id, invoice_status, invoice_details FROM Invoices;
SELECT Clients.client_id, COUNT(Invoices.invoice_id) AS invoice_count FROM Clients INNER JOIN Invoices ON Clients.client_id = Invoices.client_id GROUP BY Clients.client_id;
SELECT DISTINCT client_id, COUNT(*) AS total_invoices_per_client FROM Clients JOIN Invoices ON Clients.client_id = Invoices.client_id GROUP BY Clients.client_id;
SELECT client_id, detail, COUNT(*) AS invoice_count FROM Clients INNER JOIN Invoices ON Clients.client_id = Invoices.client_id GROUP BY client_id ORDER BY invoice_count DESC LIMIT 1;
SELECT client_id, client_details FROM Clients INNER JOIN Invoices ON Clients.client_id = Invoices.client_id INNER JOIN Staff ON Invoices.invoice_id = Staff_in_Meetings.invoice_id ORDER BY client_id DESC LIMIT 1;
SELECT client_id FROM Clients WHERE client_id IN (SELECT client_id FROM Invoices JOIN Clients ON Invoices.client_id = Clients.client_id WHERE Invoices.invoice_status = '2' GROUP BY client_id)
SELECT C.client_id FROM Clients C JOIN Invoices I ON C.client_id = I.client_id JOIN Staff_in_Meetings S ON I.invoice_id = S.meeting_id WHERE I.invoice_status = '2' AND S.staff_id = S.staff_id;
SELECT invoice_status, COUNT(invoice_id) AS invoice_count FROM Invoices GROUP BY invoice_status
SELECT DISTINCT invoice_status, COUNT(*) AS count FROM Invoices GROUP BY invoice_status;
SELECT MAX(invoice_status) AS invoice_status_code, COUNT(*) AS number_of_invoices FROM Invoices GROUP BY invoice_status ORDER BY number_of_invoices DESC;
SELECT invoice_status FROM Invoices GROUP BY invoice_status ORDER BY invoice_status DESC LIMIT 1
SELECT C.client_id, C.client_details, A.agency_id, A.agency_details, I.invoice_status, I.invoice_details FROM Clients C JOIN Agencies A ON C.agency_id = A.agency_id JOIN Invoices I ON C.client_id = I.client_id;
SELECT invoice_status, invoice_details, client_id, client_details, agency_id, agency_details FROM Invoices JOIN Clients ON Invoices.client_id = Clients.client_id JOIN Agencies ON Clients.agency_id = Agencies.agency_id;
SELECT m.meeting_type, m.client_id, m.meeting_outcome, m.billable_yn, m.start_date_time, m.end_date_time, m.purpose_of_meeting, m.other_details FROM Meetings m JOIN Clients c ON m.client_id = c.client_id;
SELECT meetings.meeting_type, meetings.client_id, meetings.start_date_time, meetings.end_date_time, meetings.purpose_of_meeting, meetings.other_details FROM Meetings;
SELECT meetings.meeting_outcome, meetings.purpose_of_meeting, meetings.billable_yn, meetings.start_date_time, meetings.end_date_time, meetings.meeting_type, meetings.other_details FROM Meetings JOIN Clients ON Clients.client_id = Meetings.client_id JOIN Staff ON Staff.staff_id = Staff_in_Meetings.staff_id JOIN Agencies ON Agencies.agency_id = Clients.agency_id JOIN Staff_in_Meetings ON Staff_in_Meetings.meeting_id = Meetings.meeting_id;
SELECT meeting_outcome, purpose_of_meeting FROM Meetings;
SELECT Payments.payment_id, Invoices.invoice_id, Invoices.invoice_details FROM Invoices INNER JOIN Payments ON Invoices.invoice_id = Payments.invoice_id WHERE Invoices.invoice_status = 'Working'
SELECT Payments.payment_id, Invoices.invoice_id, Payments.payment_details FROM Payments INNER JOIN Invoices ON Payments.invoice_id = Invoices.invoice_id WHERE Invoices.invoice_status = 'Working' AND Payments.payment_details IS NOT NULL;
SELECT invoice_id, invoice_status FROM Invoices WHERE invoice_details IS NULL;
SELECT invoice_id, invoice_status FROM Invoices WHERE invoice_status IS NULL
SELECT COUNT(*) FROM Payments
SELECT COUNT(*) FROM Payments;
SELECT Payments.payment_id, Invoices.invoice_id, Invoices.invoice_details FROM Payments INNER JOIN Invoices ON Payments.invoice_id = Invoices.invoice_id;
SELECT Payments.payment_id, Invoices.invoice_id, Payments.payment_details FROM Payments JOIN Invoices ON Payments.invoice_id = Invoices.invoice_id;
SELECT DISTINCT invoice_id, invoice_status FROM Invoices;
SELECT DISTINCT invoice_id, invoice_status FROM Invoices;
SELECT invoice_id, COUNT(p.payment_details.payment_id) AS payment_count FROM Invoices INNER JOIN Payments ON Invoices.invoice_id = Payments.invoice_id GROUP BY invoice_id;
SELECT COUNT(DISTINCT invoice_id) AS total_payments FROM Invoices JOIN Payments ON Invoices.invoice_id = Payments.invoice_id;
SELECT invoice_id, invoice_status, invoice_details FROM Invoices INNER JOIN Payments ON Invoices.invoice_id = Payments.invoice_id INNER JOIN Agencies ON Invoices.client_id = Agencies.agency_id INNER JOIN Staff IN Meetings ON Invoices.client_id = Staff.staff_id INNER JOIN Clients ON Clients.client_id = Invoices.client_id ORDER BY payments.payment_count DESC LIMIT 1;
SELECT invoice_id, invoice_status, invoice_details FROM Invoices INNER JOIN Payments ON Invoices.invoice_id = Payments.invoice_id INNER JOIN Staff_in_Meetings ON Invoices.client_id = Staff_in_Meetings.meeting_id GROUP BY invoice_id ORDER BY invoice_status DESC LIMIT 1;
SELECT COUNT(*) FROM Staff
SELECT COUNT(*) FROM Staff
SELECT Agencies.agency_id, COUNT(Staff.staff_id) AS staff_count FROM Agencies INNER JOIN Staff ON Agencies.agency_id = Staff.agency_id GROUP BY Agencies.agency_id;
SELECT agency_id, COUNT(staff_id) AS staff_count FROM Agencies INNER JOIN Staff ON Agencies.agency_id = Staff.agency_id GROUP BY agency_id;
SELECT agency_id, staff_details FROM Agencies JOIN Staff ON Agencies.agency_id = Staff.agency_id GROUP BY agency_id ORDER BY staff_details DESC LIMIT 1;
SELECT DISTINCT s.id, s.detail FROM Agencies s JOIN Staff s ON s.agency_id = s.staff_id JOIN Staff_in_Meetings s ON s.staff_id = s.staff_id JOIN Staff s2 ON s2.staff_id = s.staff_id JOIN Staff_in_Meetings s2 ON s2.staff_id = s.staff_id;
SELECT meetings.meeting_outcome, COUNT(meetings.meeting_outcome) AS num_meetings_per_outcome FROM Meetings JOIN Staff ON Meetings.meeting_id = Staff_in_Meetings.meeting_id JOIN Agencies ON Meetings.client_id = Agencies.agency_id JOIN Clients ON Meetings.client_id = Clients.client_id GROUP BY Meetings.meeting_outcome
SELECT DISTINCT meeting_outcome, COUNT(meeting_outcome) AS total_meetings FROM Meetings GROUP BY meeting_outcome;
SELECT Clients.client_id, COUNT(Meetings.client_id) AS meeting_count FROM Clients INNER JOIN Meetings ON Clients.client_id = Meetings.client_id GROUP BY Clients.client_id;
SELECT COUNT(DISTINCT client_id) AS total_meetings_per_client FROM Clients;
SELECT Clients.client_id, COUNT(Meetings.client_id) AS num_meetings FROM Clients JOIN Meetings ON Clients.client_id = Meetings.client_id GROUP BY Clients.client_id;
SELECT DISTINCT meeting_type, COUNT(meeting_type) AS total_meetings FROM Meetings GROUP BY meeting_type;
SELECT m.meeting_id, m.meeting_outcome, m.meeting_type, m.client_id, m.purpose_of_meeting, m.billable_yn, m.start_date_time, m.end_date_time, m.other_details FROM Meetings m JOIN Clients c ON m.client_id = c.client_id JOIN Agencies a ON c.agency_id = a.agency_id JOIN Staff s ON s.staff_id = Staff_in_Meetings.staff_id JOIN Staff_in_Meetings s2 ON s2.meeting_id = m.meeting_id;
SELECT Meetings.meeting_id, Meetings.client_id, Meetings.meeting_outcome, Meetings.meeting_type, Clients.client_id, Clients.client_details FROM Meetings JOIN Clients ON Meetings.client_id = Clients.client_id;
SELECT meetings.meeting_id, COUNT(staff.staff_id) AS staff_count FROM Meetings INNER JOIN Staff_in_Meetings ON Meetings.meeting_id = Staff_in_Meetings.meeting_id GROUP BY meetings.meeting_id;
SELECT COUNT(*) AS count FROM Meetings JOIN Staff_in_Meetings ON Meetings.meeting_id = Staff_in_Meetings.meeting_id;
SELECT staff_id, COUNT(*) AS attendance_count FROM Staff INNER JOIN Staff_in_Meetings ON Staff.staff_id = Staff_in_Meetings.staff_id GROUP BY staff_id HAVING COUNT(*) > 0 AND COUNT(*) = (SELECT COUNT(*) FROM Staff_in_Meetings WHERE staff_id = staff_id AND COUNT(*) > 0)
SELECT S.staff_id FROM Staff S JOIN Staff_in_Meetings ST ON S.staff_id = ST.staff_id JOIN Meetings M ON ST.meeting_id = M.meeting_id WHERE M.client_id IS NOT NULL AND M.meeting_type IS NOT NULL AND M.billable_yn IS NOT NULL AND M.start_date_time IS NOT NULL AND M.end_date_time IS NOT NULL AND M.purpose_of_meeting IS NOT NULL AND M.other_details IS NOT NULL AND S.staff_id IS NOT NULL;
